import{_ as e,o as s,c as n,a2 as t}from"./chunks/framework.BS0bAV7E.js";const m=JSON.parse('{"title":"Shell basics","description":"","frontmatter":{},"headers":[],"relativePath":"manual/shell-basics.md","filePath":"manual/shell-basics.md"}'),i={name:"manual/shell-basics.md"};function l(o,a,p,c,d,r){return s(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="shell-basics" tabindex="-1">Shell basics <a class="header-anchor" href="#shell-basics" aria-label="Permalink to &quot;Shell basics&quot;">​</a></h1><p>The <code>oc&gt;</code> shell is a Unix-flavoured command line - with pipes, redirection, background jobs, environment variables, aliases and a small scripting language. This page walks the real feature set.</p><h2 id="line-editing" tabindex="-1">Line editing <a class="header-anchor" href="#line-editing" aria-label="Permalink to &quot;Line editing&quot;">​</a></h2><ul><li>History: up/down arrows walk previous lines.</li><li>Editing within the line; <code>Ctrl+U</code> kills the line.</li><li>Input sources: PS/2 keyboard and COM1 serial feed the same queue - with <code>-serial mon:stdio</code> in QEMU you type over serial.</li></ul><h2 id="command-chaining-and-jobs" tabindex="-1">Command chaining and jobs <a class="header-anchor" href="#command-chaining-and-jobs" aria-label="Permalink to &quot;Command chaining and jobs&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; dhcp &amp;&amp; ping 10.0.2.2      (run ping only if dhcp succeeded)</span></span>
<span class="line"><span>oc&gt; cat a.txt ; cat b.txt      (sequence regardless)</span></span>
<span class="line"><span>oc&gt; health || dmesg            (second only if first failed)</span></span>
<span class="line"><span>oc&gt; ping 10.0.2.2 &amp;            (background job)</span></span>
<span class="line"><span>oc&gt; g6_test &amp;                  (long test in the background)</span></span></code></pre></div><h2 id="pipes-and-redirection" tabindex="-1">Pipes and redirection <a class="header-anchor" href="#pipes-and-redirection" aria-label="Permalink to &quot;Pipes and redirection&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; ls | grep log              (pipe stdout of ls into grep)</span></span>
<span class="line"><span>oc&gt; cat /mnt/f.txt &gt; /tmp/g.txt     (write stdout to a file)</span></span>
<span class="line"><span>oc&gt; cat /mnt/f.txt &gt;&gt; /tmp/g.txt    (append)</span></span>
<span class="line"><span>oc&gt; wget 10.0.2.2 &lt; in.txt     (stdin from a file)</span></span></code></pre></div><h2 id="wildcards" tabindex="-1">Wildcards <a class="header-anchor" href="#wildcards" aria-label="Permalink to &quot;Wildcards&quot;">​</a></h2><p><code>*</code> and <code>?</code> expand in the shell before the command runs:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; ls /mnt/*.txt</span></span>
<span class="line"><span>oc&gt; cat /mnt/report?.txt</span></span></code></pre></div><h2 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; export NAME=value          (set)</span></span>
<span class="line"><span>oc&gt; echo $NAME                 (use - $VAR expands in the line)</span></span>
<span class="line"><span>oc&gt; env                         (list all)</span></span></code></pre></div><p>Environment storage limits: 32 variables, names up to 32 bytes, values up to 256 bytes (<code>shell/shell.h</code>).</p><h2 id="aliases" tabindex="-1">Aliases <a class="header-anchor" href="#aliases" aria-label="Permalink to &quot;Aliases&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; alias ll ls -l</span></span>
<span class="line"><span>oc&gt; ll</span></span>
<span class="line"><span>oc&gt; unalias ll</span></span></code></pre></div><p>Alias values may hold full pipelines - up to 512 bytes stored in full or refused (never silently truncated). 32 alias slots.</p><h2 id="current-working-directory" tabindex="-1">Current working directory <a class="header-anchor" href="#current-working-directory" aria-label="Permalink to &quot;Current working directory&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; cd /mnt</span></span>
<span class="line"><span>oc&gt; pwd</span></span></code></pre></div><h2 id="scripting" tabindex="-1">Scripting <a class="header-anchor" href="#scripting" aria-label="Permalink to &quot;Scripting&quot;">​</a></h2><p>A script is a text file of command lines; feed it with the shell&#39;s script runner (see <code>help -a</code> for the exact command name in your build). The <code>editor</code> command gives you an in-guest full-screen text editor to write those scripts.</p><h2 id="command-help" tabindex="-1">Command help <a class="header-anchor" href="#command-help" aria-label="Permalink to &quot;Command help&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; help            (short list, one line per command)</span></span>
<span class="line"><span>oc&gt; help -a         (all 233 commands, alphabetical, with descriptions)</span></span>
<span class="line"><span>oc&gt; help -w         (the same commands grouped by the work package</span></span>
<span class="line"><span>                     that introduced them)</span></span></code></pre></div><p>The complete indexed reference with one page per command is <a href="./commands/">commands/index.md</a>.</p><h2 id="the-contract" tabindex="-1">The contract <a class="header-anchor" href="#the-contract" aria-label="Permalink to &quot;The contract&quot;">​</a></h2><p>Commands may be added across versions, never removed; names and overall behaviour of shipped commands are stable (see <a href="./../root/CONTRIBUTING.html">../CONTRIBUTING.md</a>). The command table capacity is 256 with 233 registered at present.</p>`,26)])])}const g=e(i,[["render",l]]);export{m as __pageData,g as default};
